package main

import (
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"sort"
	"strings"
	"sync"
)

type app struct {
	mu    sync.RWMutex
	names map[string]bool
}

func (a *app) add(w http.ResponseWriter, r *http.Request) {
	a.mu.Lock()
	defer a.mu.Unlock()
	a.names[r.URL.Query().Get("ism")] = true
	w.WriteHeader(http.StatusCreated)
}

func (a *app) list(w http.ResponseWriter, r *http.Request) {
	a.mu.RLock()
	defer a.mu.RUnlock()
	var all []string
	for name := range a.names {
		all = append(all, name)
	}
	sort.Strings(all)
	fmt.Fprint(w, strings.Join(all, ", "))
}

func main() {
	a := &app{names: map[string]bool{}}
	mux := http.NewServeMux()
	mux.HandleFunc("/add", a.add)
	mux.HandleFunc("/list", a.list)

	srv := httptest.NewServer(mux)
	defer srv.Close()

	for _, name := range []string{"Madina", "Aziz", "Bobur"} {
		resp, _ := http.Get(srv.URL + "/add?ism=" + name)
		resp.Body.Close()
	}
	resp, _ := http.Get(srv.URL + "/list")
	defer resp.Body.Close()
	b, _ := io.ReadAll(resp.Body)
	fmt.Println(string(b))
}

