func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/portlash", func(w http.ResponseWriter, r *http.Request) {
		panic("kutilmagan xato")
	})
	mux.HandleFunc("/ok", func(w http.ResponseWriter, r *http.Request) {
		fmt.Fprint(w, "hammasi joyida")
	})

	srv := httptest.NewUnstartedServer(mux)
	srv.Config.ErrorLog = log.New(io.Discard, "", 0) // stack trace chiqmasin
	srv.Start()
	defer srv.Close()

	_, err := http.Get(srv.URL + "/portlash")
	fmt.Println("panic so'rovida EOF:", errors.Is(err, io.EOF))

	resp, err := http.Get(srv.URL + "/ok")
	if err != nil {
		fmt.Println("xato:", err)
		return
	}
	defer resp.Body.Close()
	b, _ := io.ReadAll(resp.Body)
	fmt.Println("keyingi so'rov:", string(b))
}

