import (
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
)

func jsonXatolar(mux *http.ServeMux) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		h, pattern := mux.Handler(r)
		if pattern != "" {
			h.ServeHTTP(w, r)
			return
		}
		rec := httptest.NewRecorder() // standart 404/405 qanday kod berishini bilib olamiz
		h.ServeHTTP(rec, r)
		if allow := rec.Header().Get("Allow"); allow != "" {
			w.Header().Set("Allow", allow)
		}
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(rec.Code)
		json.NewEncoder(w).Encode(map[string]string{"xato": http.StatusText(rec.Code)})
	})
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /users/{id}", func(w http.ResponseWriter, r *http.Request) { fmt.Fprint(w, "ok") })

	srv := httptest.NewServer(jsonXatolar(mux))
	defer srv.Close()

	for _, c := range [][2]string{{"GET", "/yoq"}, {"DELETE", "/users/1"}, {"GET", "/users/1"}} {
		req, _ := http.NewRequest(c[0], srv.URL+c[1], nil)
		resp, _ := http.DefaultClient.Do(req)
		b, _ := io.ReadAll(resp.Body)
		resp.Body.Close()
		fmt.Printf("%-6s %-9s -> %d allow=%q %s\n", c[0], c[1], resp.StatusCode, resp.Header.Get("Allow"), strings.TrimSpace(string(b)))
	}
}

