	"net/http/httptest"
	"net/url"
	"strconv"
)

func intParam(q url.Values, key string, def, lo, hi int) int {
	n, err := strconv.Atoi(q.Get(key))
	if err != nil {
		return def
	}
	return max(lo, min(n, hi)) // lo..hi oralig'iga qisamiz
}

func main() {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		q := r.URL.Query()
		page := intParam(q, "page", 1, 1, 1000)
		limit := intParam(q, "limit", 10, 1, 100)
		fmt.Fprintf(w, "page=%d limit=%d offset=%d", page, limit, (page-1)*limit)
	}))
	defer srv.Close()

	for _, path := range []string{"/", "/?page=3&limit=20", "/?page=-5&limit=5000", "/?page=x"} {
		resp, _ := http.Get(srv.URL + path)
		b, _ := io.ReadAll(resp.Body)
		resp.Body.Close()
		fmt.Printf("%-22s -> %s\n", path, b)
	}
}

