	"strings"
)

func main() {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if err := r.ParseMultipartForm(1 << 20); err != nil {
			http.Error(w, "forma xato", http.StatusBadRequest)
			return
		}
		fmt.Fprintf(w, "sarlavha=%s\n", r.FormValue("sarlavha"))
		fayllar := r.MultipartForm.File["hujjat"]
		slices.SortFunc(fayllar, func(a, b *multipart.FileHeader) int {
			return strings.Compare(a.Filename, b.Filename)
		})
		for _, fh := range fayllar {
			fmt.Fprintf(w, "fayl: %s (%d bayt)\n", fh.Filename, fh.Size)
		}
	}))
	defer srv.Close()

	var body bytes.Buffer
	mw := multipart.NewWriter(&body)
	mw.WriteField("sarlavha", "Hisobotlar")
	for nom, matn := range map[string]string{"a.txt": "bir", "b.txt": "ikki uch"} {
		p, _ := mw.CreateFormFile("hujjat", nom)
		p.Write([]byte(matn))
	}
	mw.Close()

	resp, _ := http.Post(srv.URL, mw.FormDataContentType(), &body)
	defer resp.Body.Close()
	b, _ := io.ReadAll(resp.Body)
	fmt.Print(string(b))
}

