	"net/http/httptest"
	"time"
)

func main() {
	boshlandi := make(chan struct{})
	natija := make(chan error, 1)

	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		close(boshlandi)
		select {
		case <-time.After(5 * time.Second): // uzoq ish
			fmt.Fprint(w, "tayyor")
			natija <- nil
		case <-r.Context().Done(): // klient ketdi
			natija <- r.Context().Err()
		}
	}))
	defer srv.Close()

	ctx, cancel := context.WithCancel(context.Background())
	req, _ := http.NewRequestWithContext(ctx, "GET", srv.URL, nil)
	go func() {
		<-boshlandi
		cancel() // klient sabrini yo'qotdi
	}()

	_, err := http.DefaultClient.Do(req)
	fmt.Println("klient: bekor qilindi =", errors.Is(err, context.Canceled))
	fmt.Println("server:", <-natija)
}

