import (
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
)

func decodeJSON(w http.ResponseWriter, r *http.Request, dst any) (int, error) {
	r.Body = http.MaxBytesReader(w, r.Body, 64)
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields()
	err := dec.Decode(dst)
	var syn *json.SyntaxError
	var typ *json.UnmarshalTypeError
	var big *http.MaxBytesError
	switch {
	case err == nil:
		return 0, nil
	case errors.Is(err, io.EOF):
		return 400, errors.New("body bo'sh")
	case errors.As(err, &syn):
		return 400, errors.New("JSON buzuq")
	case errors.As(err, &typ):
		return 400, fmt.Errorf("%s maydoni tipi noto'g'ri", typ.Field)
	case errors.As(err, &big):
		return 413, errors.New("body juda katta")
	default:
		return 400, err
	}
}

func main() {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		var in struct {
			Yosh int `json:"yosh"`
		}
		if status, err := decodeJSON(w, r, &in); err != nil {
			http.Error(w, err.Error(), status)
			return
		}
		fmt.Fprintf(w, "yosh=%d", in.Yosh)
	}))
	defer srv.Close()

	for _, body := range []string{`{"yosh":20}`, ``, `{`, `{"yosh":"x"}`, `{"nom":1}`, `{"yosh":` + strings.Repeat("1", 80) + `}`} {
		resp, _ := http.Post(srv.URL, "application/json", strings.NewReader(body))
		b, _ := io.ReadAll(resp.Body)
		resp.Body.Close()
		fmt.Printf("%d %s", resp.StatusCode, strings.TrimSpace(string(b))+"\n")
	}
}

