import (
	"fmt"
	"sort"
	"sync"
)

type Todo struct {
	ID    int    `json:"id"`
	Title string `json:"title"`
	Done  bool   `json:"done"`
}

type Store struct {
	mu     sync.RWMutex
	nextID int
	items  map[int]Todo
}

func NewStore() *Store { return &Store{items: map[int]Todo{}} }

func (s *Store) Create(title string) Todo {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.nextID++
	t := Todo{ID: s.nextID, Title: title}
	s.items[t.ID] = t
	return t
}

func (s *Store) Get(id int) (Todo, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	t, ok := s.items[id]
	return t, ok
}

func (s *Store) List() []Todo {
	s.mu.RLock()
	defer s.mu.RUnlock()
	out := make([]Todo, 0, len(s.items))
	for _, t := range s.items {
		out = append(out, t)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

func main() {
	s := NewStore()
	s.Create("Go o'rganish")
	s.Create("API yozish")
	t, ok := s.Get(2)
	fmt.Println(t, ok)
	_, ok = s.Get(99)
	fmt.Println("99:", ok)
	fmt.Println(s.List())
}

