import (
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"sync"
)

type doc struct {
	mu      sync.Mutex
	version int
	text    string
}

func (d *doc) etag() string { return fmt.Sprintf(`"v%d"`, d.version) }

func main() {
	d := &doc{version: 1, text: "birinchi"}
	mux := http.NewServeMux()
	mux.HandleFunc("GET /doc", func(w http.ResponseWriter, r *http.Request) {
		d.mu.Lock()
		defer d.mu.Unlock()
		w.Header().Set("ETag", d.etag())
		fmt.Fprint(w, d.text)
	})
	mux.HandleFunc("PUT /doc", func(w http.ResponseWriter, r *http.Request) {
		d.mu.Lock()
		defer d.mu.Unlock()
		if r.Header.Get("If-Match") != d.etag() {
			http.Error(w, "hujjat o'zgargan, qayta yuklang", http.StatusPreconditionFailed)
			return
		}
		b, _ := io.ReadAll(r.Body)
		d.text = string(b)
		d.version++
		w.Header().Set("ETag", d.etag())
		fmt.Fprint(w, "saqlandi")
	})
	srv := httptest.NewServer(mux)
	defer srv.Close()

	resp, _ := http.Get(srv.URL + "/doc")
	resp.Body.Close()
	eski := resp.Header.Get("ETag")
	fmt.Println("o'qildi, ETag =", eski)

	for _, matn := range []string{"ikkinchi", "uchinchi"} {
		req, _ := http.NewRequest(http.MethodPut, srv.URL+"/doc", strings.NewReader(matn))
		req.Header.Set("If-Match", eski) // ikkalasi ham eski versiyaga tayanadi
		resp, _ := http.DefaultClient.Do(req)
		b, _ := io.ReadAll(resp.Body)
		resp.Body.Close()
		fmt.Printf("PUT %-9s -> %d %s", matn, resp.StatusCode, b)
		if !strings.HasSuffix(string(b), "\n") {
			fmt.Println()
		}
	}
}

