	"net/http"
	"net/http/httptest"
	"strconv"
	"strings"
	"sync"
)

type Retsept struct {
	ID     int      `json:"id"`
	Nom    string   `json:"nom"`
	Mazmun []string `json:"masalliqlar"`
}

type API struct {
	mu    sync.RWMutex
	items []Retsept
}

func respond(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	json.NewEncoder(w).Encode(v)
}

func (a *API) create(w http.ResponseWriter, r *http.Request) {
	var in Retsept
	if err := json.NewDecoder(r.Body).Decode(&in); err != nil {
		respond(w, 400, map[string]string{"error": "noto'g'ri JSON"})
		return
	}
	if strings.TrimSpace(in.Nom) == "" || len(in.Mazmun) == 0 {
		respond(w, 422, map[string]string{"error": "nom va masalliqlar majburiy"})
		return
	}
	a.mu.Lock()
	in.ID = len(a.items) + 1
	a.items = append(a.items, in)
	a.mu.Unlock()
	w.Header().Set("Location", "/retseptlar/"+strconv.Itoa(in.ID))
	respond(w, 201, in)
}

func (a *API) get(w http.ResponseWriter, r *http.Request) {
	id, _ := strconv.Atoi(r.PathValue("id"))
	a.mu.RLock()
	defer a.mu.RUnlock()
	if id < 1 || id > len(a.items) {
		respond(w, 404, map[string]string{"error": "retsept topilmadi"})
		return
	}
	respond(w, 200, a.items[id-1])
}

func main() {
	api := &API{}
	mux := http.NewServeMux()
	mux.HandleFunc("POST /retseptlar", api.create)
	mux.HandleFunc("GET /retseptlar/{id}", api.get)
	srv := httptest.NewServer(mux)
	defer srv.Close()

	send := func(method, path, body string) {
		req, _ := http.NewRequest(method, srv.URL+path, strings.NewReader(body))
		resp, _ := http.DefaultClient.Do(req)
		b, _ := io.ReadAll(resp.Body)
		resp.Body.Close()
		fmt.Printf("%-4s %-14s %d %s", method, path, resp.StatusCode, b)
	}
	send("POST", "/retseptlar", `{"nom":"Osh","masalliqlar":["guruch","sabzi","go'sht"]}`)
	send("POST", "/retseptlar", `{"nom":"Salat"}`)
	send("GET", "/retseptlar/1", "")
	send("GET", "/retseptlar/5", "")
}

