		clock = clock.Add(15 * time.Millisecond) // har chaqiruvda 15ms o'tadi
		return t
	}
	h := timing(fake)(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) { fmt.Fprint(w, "tayyor") }))

	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, httptest.NewRequest("GET", "/", nil))
