func limit(max int, next http.Handler) http.Handler {
	var mu sync.Mutex
	used := map[string]int{}
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		key := r.Header.Get("X-Client")
		mu.Lock()
		used[key]++
		n := used[key]
		mu.Unlock()
		if n > max {
			w.Header().Set("Retry-After", "60")
			http.Error(w, "juda ko'p so'rov", http.StatusTooManyRequests)
			return
		}
		next.ServeHTTP(w, r)
	})
}

func main() {
	h := limit(2, http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) { fmt.Fprint(w, "ok") }))
	for _, client := range []string{"A", "A", "A", "B", "A"} {
		req := httptest.NewRequest("GET", "/", nil)
		req.Header.Set("X-Client", client)
		rec := httptest.NewRecorder()
		h.ServeHTTP(rec, req)
		fmt.Printf("mijoz %s -> %d %s\n", client, rec.Code, rec.Header().Get("Retry-After"))
	}
}

