import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"
)

func shout(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		rec := httptest.NewRecorder()
		next.ServeHTTP(rec, r)
		for k, v := range rec.Header() {
			w.Header()[k] = v
		}
		w.WriteHeader(rec.Code)
		fmt.Fprint(w, strings.ToUpper(rec.Body.String()))
	})
}

func main() {
	h := shout(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("X-Source", "handler")
		w.WriteHeader(http.StatusAccepted)
		fmt.Fprint(w, "salom, dunyo")
	}))
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, httptest.NewRequest("GET", "/", nil))
	fmt.Println(rec.Code, rec.Body.String(), rec.Header().Get("X-Source"))
}

package main

import (
	"context"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
)

type idKey struct{}

type sw struct {
	http.ResponseWriter
	code int
}

func (s *sw) WriteHeader(c int) { s.code = c; s.ResponseWriter.WriteHeader(c) }

func requestID(next http.Handler) http.Handler {
	n := 0
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		n++
		ctx := context.WithValue(r.Context(), idKey{}, fmt.Sprintf("r%d", n))
		next.ServeHTTP(w, r.WithContext(ctx))
	})
}

func logging(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		s := &sw{ResponseWriter: w, code: 200}
		next.ServeHTTP(s, r)
		fmt.Printf("[%v] %s %s -> %d\n", r.Context().Value(idKey{}), r.Method, r.URL.Path, s.code)
	})
}

func recoverMW(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		defer func() {
			if recover() != nil {
				http.Error(w, "ichki xato", 500)
			}
		}()
		next.ServeHTTP(w, r)
	})
}

func auth(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Header.Get("Authorization") != "Bearer t" {
			http.Error(w, "kirish taqiqlangan", 401)
			return
		}
		next.ServeHTTP(w, r)
	})
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/ok", func(w http.ResponseWriter, r *http.Request) { fmt.Fprint(w, "ok") })
	mux.HandleFunc("/boom", func(w http.ResponseWriter, r *http.Request) { panic("boom") })

	srv := httptest.NewServer(requestID(logging(recoverMW(auth(mux)))))
	defer srv.Close()

	for _, c := range []struct{ path, token string }{{"/ok", "t"}, {"/ok", ""}, {"/boom", "t"}} {
		req, _ := http.NewRequest("GET", srv.URL+c.path, nil)
		if c.token != "" {
			req.Header.Set("Authorization", "Bearer "+c.token)
		}
		resp, _ := http.DefaultClient.Do(req)
		b, _ := io.ReadAll(resp.Body)
		resp.Body.Close()
		fmt.Printf("  mijoz oldi: %d %s\n", resp.StatusCode, strings.TrimSpace(string(b)))
	}
}

