import (
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
)

type StatusError struct {
	Code int
	Body string
}

func (e *StatusError) Error() string { return fmt.Sprintf("server %d qaytardi: %s", e.Code, e.Body) }

func get(url string) ([]byte, error) {
	resp, err := http.Get(url)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()

	body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
	if err != nil {
		return nil, err
	}
	if resp.StatusCode/100 != 2 {
		return nil, &StatusError{Code: resp.StatusCode, Body: string(body)}
	}
	return body, nil
}

func main() {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path == "/ok" {
			fmt.Fprint(w, "yaxshi")
			return
		}
		http.Error(w, "topilmadi", http.StatusNotFound)
	}))
	defer srv.Close()

	for _, p := range []string{"/ok", "/yoq"} {
		b, err := get(srv.URL + p)
		var se *StatusError
		switch {
		case errors.As(err, &se):
			fmt.Println("status xatosi:", se.Code)
		case err != nil:
			fmt.Println("xato:", err)
		default:
			fmt.Println("javob:", string(b))
		}
	}
}

