import (
	"context"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"net/http/httptrace"
	"strings"
)

func main() {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		fmt.Fprint(w, strings.Repeat("x", 400_000)) // 400 KB
	}))
	defer srv.Close()

	do := func(client *http.Client, drain bool) bool {
		reused := false
		trace := &httptrace.ClientTrace{GotConn: func(i httptrace.GotConnInfo) { reused = i.Reused }}
		ctx := httptrace.WithClientTrace(context.Background(), trace)
		req, _ := http.NewRequestWithContext(ctx, "GET", srv.URL, nil)
		resp, _ := client.Do(req)
		if drain {
			io.Copy(io.Discard, resp.Body)
		}
		resp.Body.Close()
		return reused
	}

	a := &http.Client{Transport: &http.Transport{}}
	do(a, false) // birinchi ulanish
	fmt.Println("o'qilmasdan yopilgach, qayta ishlatildi:", do(a, false))

	b := &http.Client{Transport: &http.Transport{}}
	do(b, true)
	fmt.Println("oxirigacha o'qilgach, qayta ishlatildi:", do(b, true))
}

