import (
	"context"
	"errors"
	"fmt"
	"net/http"
	"net/http/httptest"
	"time"
)

func main() {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		d, _ := time.ParseDuration(r.URL.Query().Get("kut"))
		select {
		case <-time.After(d):
			fmt.Fprint(w, "tayyor")
		case <-r.Context().Done():
		}
	}))
	defer srv.Close()

	for _, kut := range []string{"1ms", "300ms"} {
		ctx, cancel := context.WithTimeout(context.Background(), 60*time.Millisecond)
		req, _ := http.NewRequestWithContext(ctx, "GET", srv.URL+"?kut="+kut, nil)
		resp, err := http.DefaultClient.Do(req)
		cancel()
		if err != nil {
			fmt.Println(kut, "-> xato, timeout:", errors.Is(err, context.DeadlineExceeded))
			continue
		}
		resp.Body.Close()
		fmt.Println(kut, "->", resp.StatusCode)
	}
}

