		fmt.Println()
	}

	jar, _ := cookiejar.New(nil)
	withJar := &http.Client{Jar: jar}
	show(withJar, "/kirish")
	show(withJar, "/profil")

	noJar := &http.Client{}
	show(noJar, "/kirish")
	show(noJar, "/profil")
