func conns(disableKeepAlives bool) int64 {
	var n atomic.Int64
	srv := httptest.NewUnstartedServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		fmt.Fprint(w, "ok")
	}))
	srv.Config.ConnState = func(c net.Conn, s http.ConnState) {
		if s == http.StateNew {
			n.Add(1)
		}
	}
	srv.Start()
	defer srv.Close()

	client := &http.Client{Transport: &http.Transport{DisableKeepAlives: disableKeepAlives}}
	for i := 0; i < 3; i++ {
		resp, _ := client.Get(srv.URL)
		io.Copy(io.Discard, resp.Body)
		resp.Body.Close()
	}
	return n.Load()
}

func main() {
