	"net/http/httptest"
	"time"
)

func getWithRetry(url string, attempts int, base time.Duration) (string, error) {
	var lastErr error
	delay := base
	for i := 1; i <= attempts; i++ {
		resp, err := http.Get(url)
		if err == nil {
			body, _ := io.ReadAll(resp.Body)
			resp.Body.Close()
			if resp.StatusCode < 500 {
				return string(body), nil
			}
			err = fmt.Errorf("server %d qaytardi", resp.StatusCode)
		}
		lastErr = err
		fmt.Printf("urinish %d: %v; %v kutamiz\n", i, err, delay)
		time.Sleep(delay)
		delay *= 2
	}
	return "", fmt.Errorf("%d urinishdan keyin: %w", attempts, lastErr)
}

func main() {
	calls := 0
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		calls++
		if calls < 3 {
			http.Error(w, "band", http.StatusServiceUnavailable)
			return
		}
		fmt.Fprint(w, "nihoyat javob")
	}))
	defer srv.Close()

	body, err := getWithRetry(srv.URL, 5, 2*time.Millisecond)
	fmt.Println(body, err, "| so'rovlar:", calls)
}

