import (
	"errors"
	"fmt"
	"net/http"
)

func shouldRetry(method string, status int, err error) bool {
	idempotent := method == http.MethodGet || method == http.MethodHead ||
		method == http.MethodPut || method == http.MethodDelete
	if !idempotent {
		return false
	}
	if err != nil {
		return true // tarmoq xatosi
	}
	return status == http.StatusTooManyRequests || status >= 500
}

func main() {
	cases := []struct {
		method string
		status int
		err    error
	}{
		{"GET", 200, nil},
		{"GET", 404, nil},
		{"GET", 503, nil},
		{"GET", 429, nil},
		{"POST", 503, nil},
		{"PUT", 0, errors.New("connection reset")},
	}
	for _, c := range cases {
		fmt.Printf("%-4s %3d err=%-5v -> retry=%v\n", c.method, c.status, c.err != nil, shouldRetry(c.method, c.status, c.err))
	}
}

