import (
	"fmt"
	"time"
)

func backoff(attempt int, base, max time.Duration, jitter func(time.Duration) time.Duration) time.Duration {
	d := base << attempt // base * 2^attempt
	if d > max || d <= 0 {
		d = max
	}
	return jitter(d)
}

func main() {
	noJitter := func(d time.Duration) time.Duration { return d }
	half := func(d time.Duration) time.Duration { return d / 2 } // "yarim jitter" namunasi

	for attempt := 0; attempt < 7; attempt++ {
		fmt.Printf("urinish %d: %-6v jitter bilan: %v\n",
			attempt, backoff(attempt, 100*time.Millisecond, 3*time.Second, noJitter),
			backoff(attempt, 100*time.Millisecond, 3*time.Second, half))
	}
}

