import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"time"
)

type User struct {
	ID   int    `json:"id"`
	Name string `json:"name"`
}

type API struct {
	BaseURL string
	HTTP    *http.Client
}

func doJSON[T any](ctx context.Context, a *API, method, path string) (T, error) {
	var out T
	req, err := http.NewRequestWithContext(ctx, method, a.BaseURL+path, nil)
	if err != nil {
		return out, err
	}
	resp, err := a.HTTP.Do(req)
	if err != nil {
		return out, fmt.Errorf("%s %s: %w", method, path, err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return out, fmt.Errorf("%s %s: status %d", method, path, resp.StatusCode)
	}
	return out, json.NewDecoder(resp.Body).Decode(&out)
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /users/{id}", func(w http.ResponseWriter, r *http.Request) {
		if r.PathValue("id") != "1" {
			http.NotFound(w, r)
			return
		}
		json.NewEncoder(w).Encode(User{ID: 1, Name: "Aziz"})
	})
	srv := httptest.NewServer(mux)
	defer srv.Close()

	api := &API{BaseURL: srv.URL, HTTP: &http.Client{Timeout: time.Second}}
	u, err := doJSON[User](context.Background(), api, "GET", "/users/1")
	fmt.Println(u, err)
	_, err = doJSON[User](context.Background(), api, "GET", "/users/99")
	fmt.Println(err)
}

