		done <- run(ctx, ln, http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			fmt.Fprint(w, "ishlayapman")
		}))
	}()

	resp, _ := http.Get("http://" + ln.Addr().String())
	b, _ := io.ReadAll(resp.Body)
	resp.Body.Close()
