	"net"
	"net/http"
	"sync/atomic"
	"time"
)

func main() {
	var ready atomic.Bool
	ready.Store(true)

	mux := http.NewServeMux()
	mux.HandleFunc("GET /readyz", func(w http.ResponseWriter, r *http.Request) {
		if !ready.Load() {
			w.WriteHeader(http.StatusServiceUnavailable)
			return
		}
		w.WriteHeader(http.StatusOK)
	})
	srv := &http.Server{Handler: mux}
	ln, _ := net.Listen("tcp", "127.0.0.1:0")
	go srv.Serve(ln)
	url := "http://" + ln.Addr().String() + "/readyz"

	status := func() int {
		resp, err := http.Get(url)
		if err != nil {
			return 0
		}
		resp.Body.Close()
		return resp.StatusCode
	}

	fmt.Println("1. oldin:", status())
	ready.Store(false)
	fmt.Println("2. readiness o'chirildi:", status())
	time.Sleep(30 * time.Millisecond) // balancer o'zgarishni sezishi uchun (real hayotda 5-10 s)
	fmt.Println("3. Shutdown:", srv.Shutdown(context.Background()))
	fmt.Println("4. keyin ulanib bo'ladimi:", status() != 0)
}

package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"net/http/httptest"
)

type check func() error

func readyz(checks map[string]check) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		result := map[string]string{}
		status := http.StatusOK
		for name, c := range checks {
			if err := c(); err != nil {
				result[name] = err.Error()
				status = http.StatusServiceUnavailable
			} else {
				result[name] = "ok"
			}
		}
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(status)
		json.NewEncoder(w).Encode(result)
	}
}

func main() {
	dbOK := true
	h := readyz(map[string]check{
		"db": func() error {
			if !dbOK {
				return errors.New("ulanish yo'q")
			}
			return nil
		},
		"kesh": func() error { return nil },
	})
	srv := httptest.NewServer(h)
	defer srv.Close()

	for _, ok := range []bool{true, false} {
		dbOK = ok
		resp, _ := http.Get(srv.URL)
		var body map[string]string
		json.NewDecoder(resp.Body).Decode(&body)
		resp.Body.Close()
		fmt.Println(resp.StatusCode, body)
	}
}

