func main() {
	var mu sync.Mutex
	counts := map[string]int{}

	srv := httptest.NewUnstartedServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		fmt.Fprint(w, "ok")
	}))
	srv.Config.ConnState = func(c net.Conn, s http.ConnState) {
		mu.Lock()
		counts[s.String()]++
		mu.Unlock()
	}
	srv.Start()

	for i := 0; i < 3; i++ {
		resp, _ := http.Get(srv.URL)
		io.Copy(io.Discard, resp.Body)
		resp.Body.Close()
	}
	srv.Close() // barcha ulanishlar yopilgunicha kutadi

	mu.Lock()
	defer mu.Unlock()
	var keys []string
	for k := range counts {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		fmt.Printf("%-7s %d\n", k, counts[k])
	}
}

