import (
	"fmt"
	"net"
	"net/http"
	"net/http/httptest"
	"strings"
)

func clientIP(r *http.Request, trusted map[string]bool) string {
	host, _, _ := net.SplitHostPort(r.RemoteAddr)
	if !trusted[host] {
		return host // to'g'ridan-to'g'ri ulanish: sarlavhaga ishonmaymiz
	}
	if xff := r.Header.Get("X-Forwarded-For"); xff != "" {
		first, _, _ := strings.Cut(xff, ",")
		return strings.TrimSpace(first)
	}
	return host
}

func main() {
	trusted := map[string]bool{"10.0.0.1": true}

	cases := []struct{ remote, xff string }{
		{"10.0.0.1:5000", "203.0.113.7, 10.0.0.1"},
		{"198.51.100.9:4000", "1.2.3.4"}, // proxy emas — soxta sarlavha
		{"10.0.0.1:5001", ""},
	}
	for _, c := range cases {
		req := httptest.NewRequest("GET", "/", nil)
		req.RemoteAddr = c.remote
		if c.xff != "" {
			req.Header.Set("X-Forwarded-For", c.xff)
		}
		fmt.Printf("%-18s xff=%-22q -> %s\n", c.remote, c.xff, clientIP(req, trusted))
	}
}

