import (
	"context"
	"errors"
	"fmt"
	"net"
	"net/http"
	"time"
)

type closer struct {
	name string
	err  error
}

func (c closer) Close() error { return c.err }

func shutdownAll(ctx context.Context, srv *http.Server, resources ...closer) error {
	errs := []error{}
	if err := srv.Shutdown(ctx); err != nil {
		errs = append(errs, fmt.Errorf("server: %w", err))
	}
	for _, r := range resources {
		if err := r.Close(); err != nil {
			errs = append(errs, fmt.Errorf("%s: %w", r.name, err))
		}
	}
	return errors.Join(errs...)
}

func main() {
	srv := &http.Server{Handler: http.NewServeMux()}
	ln, _ := net.Listen("tcp", "127.0.0.1:0")
	go srv.Serve(ln)
	time.Sleep(20 * time.Millisecond)

	err := shutdownAll(context.Background(), srv,
		closer{"baza", nil},
		closer{"kesh", errors.New("ulanish allaqachon yopilgan")},
		closer{"log fayli", errors.New("flush bajarilmadi")},
	)
	fmt.Println(err)
}

