package main

import (
	"context"
	"fmt"
	"io"
	"net"
	"net/http"
	"sync/atomic"
	"time"
)

type App struct {
	ready atomic.Bool
	srv   *http.Server
}

func NewApp() *App {
	a := &App{}
	mux := http.NewServeMux()
	mux.HandleFunc("GET /readyz", func(w http.ResponseWriter, r *http.Request) {
		if !a.ready.Load() {
			http.Error(w, "tayyor emas", http.StatusServiceUnavailable)
			return
		}
		fmt.Fprint(w, "tayyor")
	})
	mux.HandleFunc("GET /ish", func(w http.ResponseWriter, r *http.Request) {
		time.Sleep(60 * time.Millisecond)
		fmt.Fprint(w, "ish bajarildi")
	})
	a.srv = &http.Server{Handler: mux, ReadHeaderTimeout: 5 * time.Second}
	return a
}

func (a *App) Run(ctx context.Context, ln net.Listener) error {
	go a.srv.Serve(ln)
	a.ready.Store(true)
	fmt.Println("[app] ishga tushdi")

	<-ctx.Done()
	fmt.Println("[app] yopilish boshlandi")
	a.ready.Store(false)
	shutdownCtx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()
	err := a.srv.Shutdown(shutdownCtx)
	fmt.Println("[app] toza yopildi")
	return err
}

func main() {
	ln, _ := net.Listen("tcp", "127.0.0.1:0")
	base := "http://" + ln.Addr().String()
	app := NewApp()
	ctx, stop := context.WithCancel(context.Background())

	done := make(chan error, 1)
	go func() { done <- app.Run(ctx, ln) }()

	get := func(path string) string {
		resp, _ := http.Get(base + path)
		defer resp.Body.Close()
		b, _ := io.ReadAll(resp.Body)
		return fmt.Sprintf("%d %s", resp.StatusCode, b)
	}
	for !app.ready.Load() {
		time.Sleep(time.Millisecond)
	}
	fmt.Println("/readyz ->", get("/readyz"))

	result := make(chan string, 1)
	go func() { result <- get("/ish") }()
	time.Sleep(20 * time.Millisecond) // /ish so'rovi hozir ishlamoqda
	stop()                            // "SIGTERM"

	res, err := <-result, <-done // avval Run tugaydi, keyin natijalarni chiqaramiz
	fmt.Println("/ish    ->", res)
	fmt.Println("Run xatosi:", err)
}

